// Role skill profiles — the V1 source of truth for what each role requires.
//
// Hand-authored on purpose. The product's entire gap analysis rests on these
// requirements being right, so they are version-controlled, reviewable, and
// diffable rather than generated by a model at runtime. An LLM asked "what
// does a frontend engineer need?" produces a plausible list with no
// accountability; when it is wrong, every downstream gap and readiness score
// inherits the error silently.
//
// Calibrated for the PRD's target user: a final-year CS student or recent
// graduate in Nepal applying for their first engineering role. Importance
// answers "would a hiring manager screening juniors expect evidence of this?",
// NOT "is this important in the industry at large". Kubernetes matters
// industry-wide; expecting it from a new graduate would produce a discouraging
// and useless roadmap.
//
// Bump seedVersion on any role whose requirements change — it is copied into
// every roleSnapshot, which is what makes an old score diagnosable later.
import { SkillImportance } from "../src/generated/client/index.js";

export type SeedSkill = {
  slug: string;
  name: string;
  // Lowercase match terms. These are handed to the evidence agent so it can
  // recognize "Express" as Node.js evidence without inventing vocabulary.
  aliases: string[];
  category: string;
};

export type SeedRequirement = {
  skillSlug: string;
  importance: SkillImportance;
  rationale: string;
};

export type SeedRole = {
  slug: string;
  title: string;
  description: string;
  seedVersion: string;
  requirements: SeedRequirement[];
};

export const SEED_VERSION = "2026-08-08.1";

